import { util } from '@aws-appsync/utils';

// Bounded, single-page count over TypeDateIndex for the given date range.
// Admin uses Select=COUNT (cheap, no per-item RBAC needed). Non-admin uses
// ALL_PROJECTED_ATTRIBUTES and counts only rows visible under the same
// owner/sharedWith/project rule as listCallsDateRange.
// Caveat: this is a single Query page (~1MB), same cap as any other native
// Query. For date ranges wider than that, `truncated` is set and the count
// under-reports rather than looping internally (no Lambda in this design).
export function request(ctx) {
  const { startDateTime, endDateTime } = ctx.arguments;
  const groups = ctx.identity.groups ? ctx.identity.groups : [];
  const isAdmin = groups.includes('Admin');
  const lo = `ts#${startDateTime}`;
  const hi = `ts#${endDateTime}#~`;

  const base = {
    operation: 'Query',
    index: 'TypeDateIndex',
    query: {
      expression: '#it = :itemType AND #sk BETWEEN :lo AND :hi',
      expressionNames: { '#it': 'ItemType', '#sk': 'SK' },
      expressionValues: util.dynamodb.toMapValues({
        ':itemType': 'call',
        ':lo': lo,
        ':hi': hi,
      }),
    },
  };

  if (isAdmin) {
    return { ...base, select: 'COUNT' };
  }
  return { ...base, select: 'ALL_PROJECTED_ATTRIBUTES' };
}

export function response(ctx) {
  const groups = ctx.identity.groups ? ctx.identity.groups : [];
  const isAdmin = groups.includes('Admin');
  const truncated = ctx.result.nextToken ? true : false;

  if (isAdmin) {
    return { count: ctx.result.count ? ctx.result.count : 0, truncated };
  }

  const me = ctx.identity.username;
  const myProjects = ctx.stash.myProjectIds ? ctx.stash.myProjectIds : [];
  const items = ctx.result.items ? ctx.result.items : [];
  let count = 0;
  for (const item of items) {
    const sharedWith = typeof item.SharedWith === 'string' ? item.SharedWith : '';
    const excluded = item.ExcludedUsers ? item.ExcludedUsers : [];
    const inShared = sharedWith.includes(me);
    const inProject = item.ProjectId && myProjects.includes(item.ProjectId) && !excluded.includes(me);
    if (item.Owner === me || inShared || inProject) {
      count += 1;
    }
  }
  return { count, truncated };
}
